"""«Вера» — ИИ-администратор загородного отеля «Берег»: даты и гости из свободного текста, цены по ночам, бронь, услуги."""
from ..ai import FAQ_COMMON
from ._t import theme

JS = r"""
(function(){var K=AIK,MN=['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'],
 MR=['январ','феврал','март','апрел','ма[йя]','июн','июл','август','сентябр','октябр','ноябр','декабр'],WD=['вс','пн','вт','ср','чт','пт','сб'],
 R=[{k:'std',n:'Стандарт с видом на лес',s:'24 м² · двуспальная кровать · до 2 гостей',p:7400,c:2},
    {k:'lake',n:'Улучшенный с видом на озеро',s:'32 м² · балкон · до 3 гостей',p:9800,c:3},
    {k:'cot',n:'Коттедж с камином',s:'68 м² · две спальни, терраса · до 5 гостей',p:16500,c:5}];
function d0(d){d=new Date(d);d.setHours(0,0,0,0);return d}
function add(d,n){d=new Date(d);d.setDate(d.getDate()+n);return d}
function fd(d){return d.getDate()+' '+MN[d.getMonth()]+', '+WD[d.getDay()]}
function rub(n){return K.fmt(n)+' ₽'}
function mon(s){for(var i=0;i<12;i++)if(new RegExp('^'+MR[i]).test(s))return i;return-1}
function mk(day,m){var t=d0(new Date()),d=new Date(t.getFullYear(),m,day);if(d<t)d.setFullYear(d.getFullYear()+1);return d}
function cost(r,S){var s=0,we=0;for(var i=0;i<S._n;i++){var w=add(S._in,i).getDay(),k=(w===5||w===6)?1.15:1;if(k>1)we++;s+=Math.round(r.p*k/100)*100}S._we=we;return s}
function plural(n,a,b,c){var m=n%100;if(m>10&&m<20)return c;m=n%10;return m===1?a:(m>1&&m<5?b:c)}
function dates(t,S){var m,t0=d0(new Date());
 if(m=t.match(/с\s*(\d{1,2})\s*(?:[а-яё]+\s+)?(?:по|до)\s*(\d{1,2})\s*([а-яё]+)/i)){var mo=mon(m[3].toLowerCase());if(mo>=0){S._in=mk(+m[1],mo);S._out=new Date(S._in);S._out.setDate(+m[2]);if(S._out<=S._in)S._out.setMonth(S._out.getMonth()+1)}}
 else if(m=t.match(/(\d{1,2})\s*[-–—]\s*(\d{1,2})\s*([а-яё]+)/i)){mo=mon(m[3].toLowerCase());if(mo>=0){S._in=mk(+m[1],mo);S._out=new Date(S._in);S._out.setDate(+m[2]);if(S._out<=S._in)S._out.setMonth(S._out.getMonth()+1)}}
 else if(m=t.match(/с\s*(\d{1,2})\s*([а-яё]+)/i)){mo=mon(m[2].toLowerCase());if(mo>=0){S._in=mk(+m[1],mo);S._out=null}}
 else if(/выходн/i.test(t)){S._in=add(t0,(5-t0.getDay()+7)%7||7);S._out=add(S._in,2)}
 else if(/послезавтра/i.test(t)){S._in=add(t0,2);S._out=null}else if(/завтра/i.test(t)){S._in=add(t0,1);S._out=null}
 if(m=t.match(/на\s*(\d{1,2}|одн\S+|дв[ае]|три|четыре|пять|недел\S+)\s*(?:ноч|сут|дн|дня)?/i)){var q=m[1].toLowerCase(),n=/^\d/.test(q)?+q:/одн/.test(q)?1:/дв/.test(q)?2:/три/.test(q)?3:/четыре/.test(q)?4:/пять/.test(q)?5:7;
  if(/ноч|сут|дн|недел/.test(m[0])&&n>0&&n<31&&S._in)S._out=add(S._in,n)}
 if(!S._in){var w2=t0.getDay(),a2=(5-w2+7)%7||7;S._in=add(t0,a2);S._out=add(S._in,2)}
 if(!S._out||S._out<=S._in)S._out=add(S._in,S._n||2);
 S._n=Math.round((S._out-S._in)/864e5);S['Заезд']=fd(S._in);S['Выезд']=fd(S._out);S['Ночей']=String(S._n)}
function guests(t,S){var g=0;if(/один|одна|двое|вдво|трое|втро|четвер|\d\s*(?:человек|взросл|гост)|реб[её]н|дет(?:ьми|ей|и)/i.test(t))S._kids=0;
 if(/вчетвером|четверо|на четверых|4\s*(?:человек|взросл|гост)/i.test(t))g=4;else if(/втро[её]м|трое|на троих|3\s*(?:человек|взросл|гост)/i.test(t))g=3;
 else if(/вдво[её]м|двое|на двоих|с жен|с муж|с парн|с девуш|2\s*(?:человек|взросл|гост)/i.test(t))g=2;else if(/один|одна|на одного/i.test(t))g=1;
 if(/реб[её]н|дет(?:ьми|ей|и)|малыш/i.test(t)){var k=/(?:дв(?:умя|ое|а)|2)\s*(?:дет|реб)/i.test(t)?2:1;S._kids=k;if(g<=2)g=(g||2)+k}
 if(g){S._g=g;S['Гостей']=g+(S._kids?' (детей: '+S._kids+')':'')}}
K.hook=function(t,S,it){var ov=null;if(it.id==='book'){S._room=null;S._banya=S._pet=S._res=S._shown=0}if(it.id==='banya'&&!S._res){ov='reserve';S._res=1}if(it.id==='reserve')S._res=1;S['Запрос']=it.label||'вопрос';if(it.id==='book'||/\d{1,2}\s*[а-яё]{3,}|выходн|завтра|ноч/i.test(t))dates(t,S);else if(!S._in)dates('',S);guests(t,S);if(!S._g){S._g=2;S['Гостей']='2'}
 var m=t.match(/стандарт|улучшен|озер|коттедж|камин/i);if(m){var q=m[0].toLowerCase();S._room=R[/стандарт/.test(q)?0:/улучш|озер/.test(q)?1:2]}
 S._fit=R.filter(function(r){return r.c>=S._g});if(!S._room||S._room.c<S._g)S._room=S._fit[0];
 if(it.id==='banya')S._banya=1;if(it.id==='pets')S._pet=1;
 var c=cost(S._room,S),ex=(S._banya?6000:0)+(S._pet?1000*S._n:0);S._cost=rub(c);S._total=rub(c+ex);S._pre=rub(Math.round((c+ex)*.3/100)*100);S._rn=S._room.n;S['Номер']=S._rn;
 var h=(S._in-new Date())/36e5;S._free=h>72?'бесплатно до '+fd(add(S._in,-3)):'уже с удержанием первой ночи: до заезда меньше 3 суток';return ov};
K.parts.fields=function(S){return['Запрос','Заезд','Выезд','Ночей','Гостей','Номер'].filter(function(k){return S[k]&&(k!=='Номер'||S._shown)}).map(function(k){return[k,S[k]]})};
K.parts.offer=function(S){S._shown=1;var n=S._n,out=[];
 out.push('На '+n+' '+plural(n,'ночь','ночи','ночей')+' с '+S['Заезд']+' для '+S._g+' '+plural(S._g,'гостя','гостей','гостей')+' свободно:');
 out.push({t:'items',items:S._fit.map(function(r,i){var c=cost(r,S),left=1+(S._in.getDate()*(i+3))%4;return{tag:i?'осталось '+left:'Подходит по числу гостей · осталось '+left,n:r.n,s:r.s,p:rub(c)+' за '+n+' '+plural(n,'ночь','ночи','ночей'),b:['Забронировать','reserve','Бронирую «'+r.n+'»']}})});
 cost(S._room,S);out.push('Завтрак и парковка входят в цену.'+(S._we?' Ночи с пятницы и субботы дороже на 15%, это уже учтено.':'')+(S._g>R[0].c&&S._fit.length<3?' «Стандарт» не предлагаю: он рассчитан на двоих.':''));return out};
K.parts.bookcard=function(S){S._shown=1;var rows=[['Номер',S._rn],['Заезд',S['Заезд']+', с 15:00'],['Выезд',S['Выезд']+', до 12:00'],['Гостей',S['Гостей']],['Проживание',S._cost]];
 if(S._banya)rows.push(['Баня на дровах, 2 часа','6 000 ₽']);if(S._pet)rows.push(['Питомец','1 000 ₽ × '+S._n]);
 return{t:'kv',h:S._res?'Бронь № Б-2041':'Расчёт проживания',rows:rows,sum:['Итого',S._total]}};
K.parts.reserve=function(S){return['Номер за вами. Проверьте бронь:',K.parts.bookcard(S),'Чтобы подтвердить, нужна предоплата 30% — '+S._pre+'. Ссылку на оплату отправила на почту из заявки, бронь держу 2 часа. Отмена '+S._free+'.']};
})();
"""


